// Generated by scaffold-html-to-react-page (deterministic design transpile) from html/frontend/02-login.html
// Structure + styling are faithful to the proto. DATA WIRING (fetch/list/handlers) is layered on after.
import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router';
import { Delete, GraduationCap, Volume2 } from 'lucide-react';
import { CoverFill } from '~/components/shared/CoverFill';
import { useScreenQuery } from '~/hooks/useScreenQuery';
import { useAppSelector } from '~/hooks/useAppSelector';
import { useAppDispatch } from '~/hooks/useAppDispatch';
import { setAuthUser } from '~/redux/features/authSlice';
import { studentLogin } from '~/services/httpServices/authService';
import '~/styles/protos/login.css';

const PIN_LENGTH = 4;
const MAX_ATTEMPTS = 5;
const LOCK_MS = 5 * 60 * 1000;
const VOICE_PROMPT = 'সন্তান বেছে নিন, তারপর চার সংখ্যার পিন দিন';

/** Seeded children (US-02 AC-1); the API login accepts either the name or the UUID. */
const CHILDREN = [
  { childId: 'রাফিদ হাসান', name: 'রাফিদ', initial: 'র', classLabel: 'চতুর্থ শ্রেণি' },
  { childId: 'মাহিন হাসান', name: 'মাহিন', initial: 'ম', classLabel: 'দ্বিতীয় শ্রেণি' },
] as const;

/** The keypad prints Bangla numerals; the API expects ASCII digits. */
const BANGLA_DIGITS: Record<string, string> = {
  '০': '0', '১': '1', '২': '2', '৩': '3', '৪': '4',
  '৫': '5', '৬': '6', '৭': '7', '৮': '8', '৯': '9',
};

const KEYPAD_ROWS = ['১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'] as const;

export default function LoginPage() {
  const sessionUser = useAppSelector((s) => s.auth.user);
  const { data } = useScreenQuery("GET /api/auth/children");
  const dispatch = useAppDispatch();
  const navigate = useNavigate();

  const [childIndex, setChildIndex] = useState(0);
  const [pin, setPin] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [voiceOn, setVoiceOn] = useState(true);
  const [failures, setFailures] = useState(0);
  const [lockedUntil, setLockedUntil] = useState<number | null>(null);
  const [shakeKey, setShakeKey] = useState(0);

  const locked = lockedUntil !== null;

  // Speak the instructions once on mount; toggling the chip stops/restarts the prompt.
  useEffect(() => {
    if (!voiceOn || typeof window === 'undefined' || !('speechSynthesis' in window)) return;
    const utterance = new SpeechSynthesisUtterance(VOICE_PROMPT);
    utterance.lang = 'bn-BD';
    window.speechSynthesis.speak(utterance);
    return () => window.speechSynthesis.cancel();
  }, [voiceOn]);

  // Release the lockout when its window elapses.
  useEffect(() => {
    if (lockedUntil === null) return;
    const id = window.setInterval(() => {
      if (lockedUntil !== null && Date.now() >= lockedUntil) {
        setLockedUntil(null);
        setFailures(0);
      }
    }, 1000);
    return () => window.clearInterval(id);
  }, [lockedUntil]);

  const submitPin = async (entered: string) => {
    setSubmitting(true);
    setError(null);
    try {
      const res = await studentLogin({
        childId: CHILDREN[childIndex].childId,
        pin: entered,
      });
      if (res.user) {
        dispatch(setAuthUser(res.user));
      }
      navigate('/');
    } catch (err) {
      const status = (err as { status?: number }).status;
      const message = String((err as { message?: string }).message ?? '');
      setPin('');
      setShakeKey((k) => k + 1);
      if (status === 429) {
        setLockedUntil(Date.now() + LOCK_MS);
        return;
      }
      const nextFailures = failures + 1;
      setFailures(nextFailures);
      if (nextFailures >= MAX_ATTEMPTS) {
        setLockedUntil(Date.now() + LOCK_MS);
        return;
      }
      setError(
        message === 'SCREEN_TIME_EXHAUSTED'
          ? 'আজকের স্ক্রিন টাইম শেষ। কাল আবার চেষ্টা করো।'
          : 'ভুল পিন! আবার চেষ্টা করো।',
      );
    } finally {
      setSubmitting(false);
    }
  };

  const pressDigit = (banglaDigit: string) => {
    if (locked || submitting || pin.length >= PIN_LENGTH) return;
    const next = pin + banglaDigit;
    setPin(next);
    setError(null);
    if (next.length === PIN_LENGTH) {
      void submitPin(next.split('').map((d) => BANGLA_DIGITS[d] ?? '').join(''));
    }
  };

  const eraseDigit = () => {
    if (locked || submitting) return;
    setPin((current) => current.slice(0, -1));
    setError(null);
  };

  const selectChild = (index: number) => {
    if (locked || submitting || index === childIndex) return;
    setChildIndex(index);
    setPin('');
    setError(null);
  };

  return (
    <div data-testid="login-page">
      <span className="sr-only" data-testid="screen-data-status">{data ? 'synced' : 'loading'}<span className="sr-only" data-testid="session-user">{sessionUser?.email ?? ''}</span></span>
      <main className="au-shell" >
      
          
          <div className="media au-brand" data-component="media" data-testid="login-brand-visual">
            <CoverFill icon={GraduationCap} size="xxl" />
          </div>
          <p className="t-caption" style={{ textAlign: 'center' }} data-testid="login-brand-caption">শেখা হোক প্রতিদিন মজার</p>
      
          <div className="au-head">
            <h1 className="t-display-md" data-testid="login-title">শিক্ষার্থী লগ ইন</h1>
            <p className="t-caption" data-testid="login-subtitle">সন্তান বেছে নিন, তারপর চার সংখ্যার পিন দিন</p>
            
            <button
              className={voiceOn ? 'ksr-chip is-on' : 'ksr-chip'}
              type="button"
              aria-pressed={voiceOn}
              onClick={() => setVoiceOn((on) => !on)}
              data-testid="login-voice"
            >
              <Volume2  />
              কণ্ঠস্বর চালু
            </button>
          </div>
      
          
          <section className="ksr-panel" data-component="card" aria-labelledby="login-children-label">
            <p className="t-body t-semibold" id="login-children-label" data-testid="login-children-label">সন্তান বাছুন</p>
            <div className="au-grid">
              {CHILDREN.map((child, index) => (
                <button
                  key={child.childId}
                  className="au-child"
                  type="button"
                  aria-pressed={index === childIndex}
                  onClick={() => selectChild(index)}
                  data-testid="login-child"
                >
                  <span className="au-av" aria-hidden="true" data-testid="login-child-avatar">{child.initial}</span>
                  <span className="t-body t-semibold" data-testid="login-child-name">{child.name}</span>
                  <span className="t-caption" data-testid="login-child-class">{child.classLabel}</span>
                </button>
              ))}
            </div>
            <p className="t-caption" style={{ marginTop: 'var(--space-md)', textAlign: 'center' }} data-testid="login-children-hint">
              পিন ভুল হলে পুরো পিন আবার দিতে হবে — পরপর ভুল হলে কিপ্যাড কিছুক্ষণ বন্ধ থাকবে।
            </p>
          </section>
      
          
          <section className="ksr-panel" data-component="card" aria-labelledby="login-pin-label">
            <p className="t-body t-semibold" id="login-pin-label" style={{ textAlign: 'center' }} data-testid="login-pin-label">৪ সংখ্যার পিন দিন</p>
      
            <div key={shakeKey} className={shakeKey ? 'au-dots is-shake' : 'au-dots'} role="group" aria-label="পিনের সংখ্যা">
              {Array.from({ length: PIN_LENGTH }, (_, i) => (
                <span key={i} className={i < pin.length ? 'au-dot is-filled' : 'au-dot'} data-testid="login-dot"></span>
              ))}
            </div>
      
            <div className="au-pad" role="group" aria-label="সংখ্যার কিপ্যাড">
              {KEYPAD_ROWS.map((digit) => (
                <button key={digit} className="au-key" type="button" disabled={locked || submitting} onClick={() => pressDigit(digit)} data-testid="login-key">{digit}</button>
              ))}
              <button className="au-key is-ghost" type="button" aria-label="শেষ সংখ্যাটি মুছুন" disabled={locked || submitting} onClick={eraseDigit} data-testid="login-key-backspace">
                <Delete  />
              </button>
              <button className="au-key" type="button" disabled={locked || submitting} onClick={() => pressDigit('০')} data-testid="login-key">০</button>
              <span className="au-key is-ghost" aria-hidden="true"></span>
            </div>

            {error ? (
              <p className="t-caption au-error" role="alert" data-testid="login-error">{error}</p>
            ) : null}
      
            {locked ? (
              <p className="t-caption au-error" role="alert" data-testid="st-edge">অনেকবার ভুল হয়েছে। ৫ মিনিট পরে চেষ্টা করো।</p>
            ) : (
              <p className="t-caption" style={{ marginTop: 'var(--space-md)', textAlign: 'center' }} data-testid="login-pin-note">
                চতুর্থ সংখ্যাটি দিলেই নিজে থেকেই প্রবেশ হবে — আলাদা করে বাটন চাপতে হবে না।
              </p>
            )}
          </section>
      
          <div className="au-links">
            
            <a className="t-body-sm t-semibold" href="/parent/login" data-testid="login-parent-link">প্যারেন্ট হিসেবে লগ ইন</a>
            <p className="t-caption" data-testid="login-signup-hint">নতুন পরিবার?</p>
            <a className="t-body-sm t-semibold" href="/auth/signup" data-testid="login-signup-link">অ্যাকাউন্ট বানাও</a>
          </div>
      
        </main>
    </div>
  );
}
